#!/bin/bash
# SPDX-License-Identifier: Apache-2.0
# Build a signed OneMind OTA bundle for Jetson on the owner's x86-64 Linux host: NVIDIA's
# image-based OTA payload (generated by NVIDIA's l4t_generate_ota_package.sh from a target tree
# made by build-flash-package.sh) wrapped in OneMind's release contract (01 §4.2 items 1 and 4):
#
#   <out>/ota_payload_package.tar.gz      NVIDIA's payload (unsigned by NVIDIA [C-REF3-DC-security-001])
#   <out>/ota_tools_R<l4t>_aarch64.tbz2   NVIDIA's OTA tools, pinned sha256, with OTA_MAX_RETRY_COUNT > 0
#   <out>/manifest.json                   version, compatible, layout flags, L4T from/to, QSPI, sha256s, expiry
#   <out>/manifest.json.p7s               CMS signature by the OneMind release CA (the RAUC trust root)
#
#   sudo os/boards/jetson-orin/build-ota-bundle.sh --base <work-of-base>/Linux_for_Tegra \
#        --target <work-of-target>/Linux_for_Tegra --base-l4t 36.5.2 --target-l4t 39.2.1 \
#        --downloads <dir> --device-layout <jetson-layout.json recorded at the device's flash> \
#        --cert <ca.pem> --key <ca.key> --out <dir> [--requires-qspi <ver>] [--rootfs-size <S>] [--days 90]
#
# Like the flash package, the bundle contains NVIDIA's BSP files and the owner's Ubuntu-based
# rootfs: it stays with the owner (Z-01). The device side is `onemind-jetson ota-apply <dir>`.
set -euo pipefail
HERE=$(cd "$(dirname "$0")" && pwd)
# shellcheck source=os/boards/jetson-orin/pins.sh
. "$HERE/pins.sh"
BASE=""; TARGET=""; BL4T=""; TL4T=""; DL=""; DLAYOUT=""; CERT=""; KEY=""; OUT=""; QSPI=""; RSIZE=""; DAYS=90
TARGET_BOARD=jetson-orin-nano-devkit; EXTDEV=nvme0n1; OTA_RETRY=3
die() { echo "build-ota-bundle: $*" >&2; exit 1; }
while [ $# -gt 0 ]; do
  case "$1" in
  --base) BASE=$2; shift 2 ;;            --target) TARGET=$2; shift 2 ;;
  --base-l4t) BL4T=$2; shift 2 ;;        --target-l4t) TL4T=$2; shift 2 ;;
  --downloads) DL=$2; shift 2 ;;         --device-layout) DLAYOUT=$2; shift 2 ;;
  --cert) CERT=$2; shift 2 ;;            --key) KEY=$2; shift 2 ;;
  --out) OUT=$2; shift 2 ;;              --requires-qspi) QSPI=$2; shift 2 ;;
  --rootfs-size) RSIZE=$2; shift 2 ;;    --days) DAYS=$2; shift 2 ;;
  *) die "unknown option $1" ;;
  esac
done
[ "$(uname -s)" = Linux ] && [ "$(uname -m)" = x86_64 ] || die "run on an x86-64 Linux host"
[ "$(id -u)" = 0 ] || die "run with sudo (NVIDIA's payload generator needs root)"
for v in BASE TARGET BL4T TL4T DL DLAYOUT CERT KEY OUT; do [ -n "${!v}" ] || die "missing --$(echo "$v" | tr '[:upper:]' '[:lower:]')"; done
[ -f "$TARGET/rootfs/etc/onemind/release" ] || die "$TARGET is not a OneMind tree (build-flash-package.sh)"
VERSION=$(sed -n 's/^ONEMIND_VERSION=//p' "$TARGET/rootfs/etc/onemind/release")
pins_for "$BL4T" >/dev/null; BSP_ARG=$L4T_BSP_ARG
pins_for "$TL4T"
echo "$L4T_OTA_TOOLS_SHA256  $DL/$L4T_OTA_TOOLS" | sha256sum -c - || die "$L4T_OTA_TOOLS missing or not the pinned file"

# NVIDIA's OTA tools into the target tree, then OTA_MAX_RETRY_COUNT > 0: its default 0 leaves a
# device whose OTA was interrupted at a recovery shell [C-W3-051]. Text configuration only;
# NVIDIA's binaries are never modified (C-LIC-003).
tar -xpf "$DL/$L4T_OTA_TOOLS" -C "$TARGET/.."
V="$TARGET/tools/ota_tools/version_upgrade"
sed -i "s/^OTA_MAX_RETRY_COUNT=.*/OTA_MAX_RETRY_COUNT=$OTA_RETRY/" "$V/nv_ota_run_tasks.sh"
grep -qx "OTA_MAX_RETRY_COUNT=$OTA_RETRY" "$V/nv_ota_run_tasks.sh" || die "could not set OTA_MAX_RETRY_COUNT"
sed -i 's/^PRESERVE_LOGS=.*/PRESERVE_LOGS="true"/' "$V/nv_ota_customer.conf"

# Layout flags this payload is built with; ota-sign refuses them if they differ from the device's.
SOPT=(); [ -n "$RSIZE" ] && SOPT=(-S "$RSIZE")
PL="$(mktemp -d)/payload-layout.json"
python3 -I "$HERE/jetson_layout.py" record --out "$PL" --layout-xml "$TARGET/tools/kernel_flash/onemind_t234_nvme_rootfs_ab.xml" \
  --layout-xml-name tools/kernel_flash/onemind_t234_nvme_rootfs_ab.xml --l4t "$TL4T" --target-board "$TARGET_BOARD" \
  --external-device "$EXTDEV" --rootfs-size "${RSIZE:-nvidia-default}"

(cd "$TARGET" && BASE_BSP=$(cd "$BASE" && pwd) TARGET_BSP=$(pwd) ROOTFS_AB=1 \
  ./tools/ota_tools/version_upgrade/l4t_generate_ota_package.sh --external-device "$EXTDEV" "${SOPT[@]}" \
  "$TARGET_BOARD" "$BSP_ARG")
P="$TARGET/bootloader/$TARGET_BOARD/ota_payload_package.tar.gz"
[ -f "$P" ] || die "NVIDIA's generator left no $P"

mkdir -p "$OUT"; [ -z "$(ls -A "$OUT")" ] || die "--out $OUT is not empty"
cp "$P" "$OUT/"
cp "$DL/$L4T_OTA_TOOLS" "$OUT/"
# The on-device tools must carry the same retry setting as the payload's recovery task runner.
T=$(mktemp -d); tar -xpf "$OUT/$L4T_OTA_TOOLS" -C "$T"
sed -i "s/^OTA_MAX_RETRY_COUNT=.*/OTA_MAX_RETRY_COUNT=$OTA_RETRY/" "$T/Linux_for_Tegra/tools/ota_tools/version_upgrade/nv_ota_run_tasks.sh"
tar -cjf "$OUT/$L4T_OTA_TOOLS" -C "$T" Linux_for_Tegra; rm -rf "$T"

J="$HERE/rootfs/usr/lib/onemind/jetson/onemind_jetson.py"
python3 -I "$J" ota-manifest "$OUT" --version "$VERSION" --layout "$PL" --l4t-from "$BL4T" --l4t-to "$TL4T" \
  --requires-qspi "${QSPI:-$BL4T}" --days "$DAYS"
python3 -I "$J" ota-sign "$OUT/manifest.json" --out "$OUT/manifest.json.p7s" --cert "$CERT" --key "$KEY" \
  --device-layout "$DLAYOUT"
openssl cms -verify -binary -inform DER -in "$OUT/manifest.json.p7s" -content "$OUT/manifest.json" \
  -CAfile "$CERT" -purpose any -out /dev/null
echo "bundle $VERSION (L4T $BL4T -> $TL4T) in $OUT; on the device: sudo onemind-jetson ota-apply <dir> --reboot"
